replace_vowels_with_numbers() {
  local input_string=$1
  local vowels="aeiouAEIOU"
  local result=""

  for ((i=0; i<${#input_string}; i++)); do
    char=${input_string:$i:1}
    if [[ $vowels == *$char* ]]; then
      case $char in
        a|A) result+="1" ;;
        e|E) result+="2" ;;
        i|I) result

